const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Digangali, Chad approximate coordinates
  const point = ee.Geometry.Point([15.4, 13.7]);
  const region = point.buffer(10000); // 10km radius buffer

  // 2. Data Acquisition & Check
  const jrcMonthly = ee.ImageCollection('JRC/GSW1_4/MonthlyHistory');

  // September 2021
  const sept2021 = jrcMonthly
    .filter(ee.Filter.date('2021-09-01', '2021-09-30'))
    .first();

  // October 2022
  const oct2022 = jrcMonthly
    .filter(ee.Filter.date('2022-10-01', '2022-10-31'))
    .first();

  // Check if images exist
  const sept2021Info = await new Promise((resolve, reject) => {
    sept2021.getInfo((result, error) => {
      if (error) resolve(null);
      else resolve(result);
    });
  });

  const oct2022Info = await new Promise((resolve, reject) => {
    oct2022.getInfo((result, error) => {
      if (error) resolve(null);
      else resolve(result);
    });
  });

  if (!sept2021Info || !oct2022Info) {
    console.log("No data available for one or both months.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Extract water pixels (value = 2)
  const water2021 = sept2021.eq(2);
  const water2022 = oct2022.eq(2);

  // 4. Calculate water extent (pixel count and area)
  const stats2021 = await new Promise((resolve, reject) => {
    water2021.reduceRegion({
      reducer: ee.Reducer.sum().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: region,
      scale: 30,
      maxPixels: 1e9
    }).getInfo((result, error) => {
      if (error) reject(error);
      else resolve(result);
    });
  });

  const stats2022 = await new Promise((resolve, reject) => {
    water2022.reduceRegion({
      reducer: ee.Reducer.sum().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: region,
      scale: 30,
      maxPixels: 1e9
    }).getInfo((result, error) => {
      if (error) reject(error);
      else resolve(result);
    });
  });

  const waterPixels2021 = stats2021.water_sum || 0;
  const totalPixels2021 = stats2021.water_count || 0;
  const waterPixels2022 = stats2022.water_sum || 0;
  const totalPixels2022 = stats2022.water_count || 0;

  // 5. Validation & Final Answer
  console.log(`Sept 2021 - Water pixels: ${waterPixels2021}, Total pixels: ${totalPixels2021}`);
  console.log(`Oct 2022 - Water pixels: ${waterPixels2022}, Total pixels: ${totalPixels2022}`);

  if (totalPixels2021 === 0 || totalPixels2022 === 0) {
    console.log("No valid pixels in region.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (waterPixels2021 === null || waterPixels2022 === null || 
      isNaN(waterPixels2021) || isNaN(waterPixels2022)) {
    console.log("Calculation failed - invalid values.");
    console.log("<answer>C3</answer>");
    return;
  }

  const waterArea2021 = waterPixels2021 * 30 * 30 / 1e6; // km²
  const waterArea2022 = waterPixels2022 * 30 * 30 / 1e6; // km²

  console.log(`Sept 2021 water area: ${waterArea2021.toFixed(3)} km²`);
  console.log(`Oct 2022 water area: ${waterArea2022.toFixed(3)} km²`);
  console.log(`Change: ${(waterArea2022 - waterArea2021).toFixed(3)} km²`);

  if (waterPixels2022 > waterPixels2021) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
